<template><div class="app-container"><div class="filter-container"><el-input v-model="query.userId" placeholder="用户ID" style="width:150px"/><el-select v-model="query.status" clearable placeholder="状态"><el-option label="待处理" value="OPEN"/><el-option label="已关注" value="ACKNOWLEDGED"/><el-option label="已关闭" value="CLOSED"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table :data="list" border><el-table-column prop="userName" label="用户"/><el-table-column prop="dataType" label="类型"/><el-table-column prop="measuredValue" label="测量值"/><el-table-column prop="alertLevel" label="风险"/><el-table-column prop="status" label="状态"/><el-table-column prop="createTime" label="产生时间" min-width="160"/><el-table-column label="操作" width="150"><template slot-scope="{row}"><el-button v-if="row.status!=='CLOSED'" type="text" @click="process(row,'ACKNOWLEDGE')">关注</el-button><el-button v-if="row.status!=='CLOSED'" type="text" @click="process(row,'CLOSE')">关闭</el-button></template></el-table-column></el-table></div></template><script>import{getJkHealthAlertRecordList,processJkHealthAlert}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[]}},created(){this.load()},methods:{load(){getJkHealthAlertRecordList(this.query).then(r=>this.list=(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[])},process(row,action){this.$prompt('处理说明','健康预警').then(({value})=>processJkHealthAlert({alertId:row.id,action,remark:value}).then(()=>{this.$message.success('处理成功');this.load()}))}}}</script>